#include <bits/stdc++.h>
using namespace std;

// Decimal text of n built digit by digit (64-bit so INT_MIN negates safely).
string digits(long long n) {
    if (n == 0) return "0";
    bool neg = n < 0;
    long long x = neg ? -n : n;
    string out;
    while (x) { out += char('0' + x % 10); x /= 10; }
    if (neg) out += '-';
    reverse(out.begin(), out.end());
    return out;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    string line, out;
    bool first = true;
    while (getline(cin, line)) {
        // parse the signed integer by hand, skipping blank lines
        size_t i = line.find_first_not_of(" \t\r");
        if (i == string::npos) continue;
        bool neg = false;
        if (line[i] == '-' || line[i] == '+') neg = line[i++] == '-';
        long long v = 0;
        while (i < line.size() && isdigit((unsigned char)line[i])) v = v * 10 + (line[i++] - '0');
        if (!first) out += '\n';
        first = false;
        out += digits(neg ? -v : v);
    }
    cout << out << "\n";
}

import java.io.*;

public class Main {
    // Decimal text of n built digit by digit (long so INT_MIN negates safely).
    static void digits(long n, StringBuilder out) {
        if (n == 0) { out.append('0'); return; }
        boolean neg = n < 0;
        long x = neg ? -n : n;
        char[] buf = new char[21];
        int p = buf.length;
        while (x > 0) { buf[--p] = (char) ('0' + x % 10); x /= 10; }
        if (neg) buf[--p] = '-';
        out.append(buf, p, buf.length - p);
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringBuilder out = new StringBuilder();
        boolean first = true;
        String line;
        while ((line = br.readLine()) != null) {
            // parse the signed integer by hand, skipping blank lines
            String t = line.strip();
            if (t.isEmpty()) continue;
            int i = 0;
            boolean neg = false;
            if (t.charAt(0) == '-' || t.charAt(0) == '+') neg = t.charAt(i++) == '-';
            long v = 0;
            while (i < t.length() && Character.isDigit(t.charAt(i))) v = v * 10 + (t.charAt(i++) - '0');
            if (!first) out.append('\n');
            first = false;
            digits(neg ? -v : v, out);
        }
        System.out.println(out);
    }
}

package main

import (
	"bufio"
	"os"
	"strings"
)

// digits appends the decimal text of n built digit by digit (int64 so INT_MIN negates safely).
func digits(n int64, w *bufio.Writer) {
	if n == 0 {
		w.WriteByte('0')
		return
	}
	neg := n < 0
	x := n
	if neg {
		x = -n
	}
	var buf [21]byte
	p := len(buf)
	for x > 0 {
		p--
		buf[p] = byte('0' + x%10)
		x /= 10
	}
	if neg {
		p--
		buf[p] = '-'
	}
	w.Write(buf[p:])
}

func main() {
	sc := bufio.NewScanner(os.Stdin)
	sc.Buffer(make([]byte, 1<<20), 1<<24)
	w := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer w.Flush()
	first := true
	for sc.Scan() {
		// parse the signed integer by hand, skipping blank lines
		t := strings.TrimSpace(sc.Text())
		if t == "" {
			continue
		}
		i, neg := 0, false
		if t[0] == '-' || t[0] == '+' {
			neg = t[0] == '-'
			i++
		}
		var v int64
		for ; i < len(t) && t[i] >= '0' && t[i] <= '9'; i++ {
			v = v*10 + int64(t[i]-'0')
		}
		if !first {
			w.WriteByte('\n')
		}
		first = false
		if neg {
			v = -v
		}
		digits(v, w)
	}
	w.WriteByte('\n')
}
